async fn rea_static_read(
	&self,
	Parameters(params): Parameters<rea_provider::ReaStaticRequest>,
) -> Result<String, String> {
	rea_provider::read(params)
		.await
		.map_err(|error| error.to_string())
}

async fn rea_static_start(
	&self,
	Parameters(params): Parameters<rea_provider::ReaStaticRequest>,
) -> Result<String, String> {
	let _owner_admission = runtime::effect_owner_fence::admit_new_effect()
		.await
		.map_err(|error| error.to_string())?;
	rea_provider::start(params)
		.await
		.map_err(|error| error.to_string())
}

async fn rea_get_evidence_bundle(
	&self,
	Parameters(params): Parameters<serde_json::Value>,
	context: RequestContext<RoleServer>,
) -> Result<CallToolResult, ErrorData> {
	let raw = context
		.extensions
		.get::<rea_mcp_transport::ReaRawArguments>();
	if let Some(error) = raw.and_then(|raw| raw.protocol_error()) {
		return Err(error);
	}
	if let Err(error) = rea_mcp_input::bundle_ordered(
		&params,
		raw.and_then(|raw| raw.object_keys(&[])),
		raw.and_then(|raw| raw.object_keys(&["filters"])),
	) {
		return Ok(error.wire());
	}
	Ok(self.rea_session.get_bundle(params))
}

async fn rea_inspect_elf_notes(
	&self,
	Parameters(params): Parameters<serde_json::Value>,
	context: RequestContext<RoleServer>,
) -> Result<CallToolResult, ErrorData> {
	let raw = context
		.extensions
		.get::<rea_mcp_transport::ReaRawArguments>();
	if let Some(error) = raw.and_then(|raw| raw.protocol_error()) {
		return Err(error);
	}
	if let Err(error) =
		rea_mcp_input::elf_ordered(&params, raw.and_then(|raw| raw.object_keys(&[])))
	{
		return Ok(error.wire());
	}
	let admission = match runtime::effect_owner_fence::admit_new_effect().await {
		Ok(permit) => Arc::new(permit),
		Err(error) => {
			return Ok(
				rea_contract::Failure::output("inspect_elf_notes", error.to_string()).wire(),
			)
		}
	};
	Ok(rea_elf_notes::inspect(params, &self.rea_session, context.ct.clone(), admission).await)
}

pub async fn read(request: ReaStaticRequest) -> Result<String> {
	let params = prepare_request(runtime_config()?, request)?;
	let Some(output) = crate::native::observe_terminal_output(&params, MAX_RESULT_BYTES).await?
	else {
		return Ok(serde_json::to_string(
			&json!({"state":"pending_or_unknown","complete":false,"observation_only":true}),
		)?);
	};
	let job = output.job_id().to_owned();
	let exit_code = output.exit_code();
	let outcome = output.outcome();
	let state = match outcome {
		crate::native::NativeJobOutcome::Succeeded => "succeeded",
		crate::native::NativeJobOutcome::Failed => "failed",
		crate::native::NativeJobOutcome::Cancelled => "cancelled",
		crate::native::NativeJobOutcome::TimedOut => "timed_out",
	};
	let process_succeeded = outcome == crate::native::NativeJobOutcome::Succeeded;
	let scratch_cleanup = output.scratch_cleanup().cloned();
	let cleanup_complete = scratch_cleanup.as_ref().map(|receipt| {
		receipt["state"] == "removed"
			&& receipt["durable"] == true
			&& receipt["worker_adopted"] == true
	});
	let (stdout, stderr) = output.into_streams();
	let mut report_error = None;
	let report = if stdout.is_empty() {
		if process_succeeded {
			bail!("successful static worker omitted its report");
		}
		Value::Null
	} else {
		let validated = (|| -> Result<Value> {
			let report = serde_json::from_slice::<Value>(&stdout)
				.context("static worker output was not a complete JSON record")?;
			let worker: WorkerRequest = serde_json::from_str(
				params
					.stdin
					.as_deref()
					.context("original static request absent")?,
			)?;
			validate_report(&report, &worker, exit_code)?;
			if scratch_cleanup.is_some() != (report["scratch"]["cleanup_owner"] == "durable_job") {
				bail!("static report and original owner disagree on scratch lifecycle");
			}
			Ok(report)
		})();
		match validated {
			Ok(report) => report,
			Err(error) if !process_succeeded => {
				// Cancellation can interrupt the final JSON write. Keep the original
				// failed/cancelled output queryable without accepting a partial report.
				report_error = Some(format!("{error:#}"));
				Value::Null
			}
			Err(error) => return Err(error),
		}
	};
	Ok(serde_json::to_string(&json!({
		"job_id":job,"state":state,"exit_code":exit_code,"process_succeeded":process_succeeded,
		"complete":true,"observation_only":true,"report":report,
		"scratch_cleanup":scratch_cleanup,"cleanup_complete":cleanup_complete,
		"worker_stdout":report_error.as_ref().map(|_| String::from_utf8_lossy(&stdout)),
		"report_error":report_error,
		"worker_stderr":String::from_utf8_lossy(&stderr),"rea_evidence_compatible":false
	}))?)
}

pub(super) fn record_with_origin(
	&self,
	evidence: Value,
	origin: RecordOrigin,
) -> Result<RetainedRecord, Failure> {
	self.record_checked(evidence, origin, || Ok(()))
}

pub(super) fn get_bundle(&self, raw: Value) -> CallToolResult {
	if let Err(error) = super::rea_mcp_input::bundle(&raw) {
		return error.wire();
	}
	let options = match BundleOptions::parse(&raw) {
		Ok(value) => value,
		Err(error) => return error.wire(),
	};
	let registry = match self.state.lock() {
		Ok(records) => records,
		Err(_) => return Failure::integrity("Evidence session registry is unavailable").wire(),
	};
	// Clone only Arc handles while holding the mutex. Response measurement
	// and encoding run against an immutable selection after releasing it.
	let selected_origins: Vec<RecordOrigin> = registry
		.records
		.values()
		.map(|entry| entry.origin)
		.collect();
	let selected_import_orders = registry
		.records
		.values()
		.map(|entry| entry.imported_order.clone())
		.collect::<Vec<_>>();
	let unknowns = registry.unknowns.clone();
	let records: BTreeMap<String, Arc<Value>> = registry
		.records
		.iter()
		.map(|(id, entry)| (id.clone(), Arc::clone(&entry.evidence)))
		.collect();
	drop(registry);
	if options.summary {
		let value = summarize(&records, &options.filters, unknowns.len());
		drop(records);
		rea_contract::success("get_evidence_bundle", json!({"result":value}), None)
	} else {
		// The view borrows payloads. Serialization checks the transport
		// bound before constructing a second owned JSON representation.
		#[derive(serde::Serialize)]
		struct ResultView<'a> {
			result: BundleView<'a>,
		}
		let complete = ResultView {
			result: bundle(&records, &unknowns),
		};
		let view = &complete.result;
		let artifacts: Vec<&Value> = view.artifacts.iter().collect();
		let providers: Vec<&Value> = view.providers.iter().collect();
		let environments: Vec<&Value> = view.environments.iter().collect();
		let scenarios: Vec<&Value> = view.scenarios.iter().collect();
		let captures: Vec<&Value> = view.captures.iter().collect();
		let unknowns: Vec<&Value> = view.unknowns.clone();
		let fields = [
			("artifacts", JsonView::Values(&artifacts)),
			("providers", JsonView::Values(&providers)),
			("environments", JsonView::Values(&environments)),
			("scenarios", JsonView::Values(&scenarios)),
			("captures", JsonView::Values(&captures)),
			("unknowns", JsonView::Values(&unknowns)),
			("records", JsonView::Values(&view.records)),
		];
		let result = [("result", JsonView::Object(&fields))];
		let order = match BundleOrder::with_imports(
			&view.records,
			&selected_origins,
			&selected_import_orders,
			&view.unknowns,
		) {
			Ok(order) => order,
			Err(error) => {
				return Failure::output("get_evidence_bundle", error.to_string()).wire()
			}
		};
		// Generic records without recorded producer provenance have no known
		// source order. Their Fits size is order independent; overflow never fabricates
		// a source order. Production producers always supply an explicit origin.
		let known = selected_origins
			.iter()
			.zip(&selected_import_orders)
			.all(|(origin, order)| *origin != RecordOrigin::Unknown || order.is_some());
		let original_order: Option<&dyn super::rea_response_encoding::ObjectOrder> =
			known.then_some(&order);
		rea_contract::deliver_view(
			"get_evidence_bundle",
			JsonView::Object(&result),
			original_order,
			None,
			false,
			true,
			|| serde_json::to_value(&complete),
		)
	}
}
